"""Demo 1: The abstract order-parameter dichotomy.

Shows that a concave increasing map F through the origin acquires a positive
fixed point exactly when its slope at the origin exceeds 1, using the test
family F_c(x) = c*x - x^3.
"""
from __future__ import annotations
from typing import Callable, Optional


def positive_fixed_point(F: Callable[[float], float], b: float = 1.0,
                         tol: float = 1e-14) -> Optional[float]:
    lo = None
    for k in range(1, 4096):
        x = b * k / 4096.0
        if F(x) - x > 0.0:
            lo = x
            break
    if lo is None:
        return None
    hi = b
    while hi - lo > tol:
        mid = 0.5 * (lo + hi)
        if F(mid) - mid > 0.0:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def run() -> None:
    for c in (0.5, 0.9, 1.0, 1.1, 1.5, 2.0):
        F = lambda x, c=c: max(0.0, c * x - x ** 3)
        fp = positive_fixed_point(F)
        print(f"slope c={c:>4}: {'x*=%.6f' % fp if fp else 'trivial 0 only'}")


if __name__ == "__main__":
    run()

"""Demo 2: Curie-Weiss vs branching survival side by side.

Solves m = tanh(beta*m) and q = 1 - exp(-mu*q) for a shared sweep of the
coupling, exhibiting the common critical value 1.
"""
from __future__ import annotations
import math
from typing import Callable, Optional


def positive_fixed_point(F: Callable[[float], float], b: float = 1.0,
                         tol: float = 1e-14) -> Optional[float]:
    lo = None
    for k in range(1, 4096):
        x = b * k / 4096.0
        if F(x) - x > 0.0:
            lo = x
            break
    if lo is None:
        return None
    hi = b
    while hi - lo > tol:
        mid = 0.5 * (lo + hi)
        if F(mid) - mid > 0.0:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def run() -> None:
    print(f"{'coupling':>9} {'magnetization m':>16} {'survival q':>12}")
    for c in (0.8, 1.0, 1.2, 1.5, 2.0, 3.0):
        m = positive_fixed_point(lambda m: math.tanh(c * m))
        q = positive_fixed_point(lambda q: 1.0 - math.exp(-c * q))
        print(f"{c:>9} {('%.6f' % m) if m else '0':>16} "
              f"{('%.6f' % q) if q else '0':>12}")


if __name__ == "__main__":
    run()
